#include<bits/stdc++.h>
#define int long long
using namespace std;
struct node{
	int x,y;
};

signed main(){
	int n,m,k;
	cin>>n>>m>>k;
	int ans=0;
	for(int i=1;i<=k;i++){
		int x=0,y=0;
		for(int j=1;j*j<=i;j++){
			if(i%j==0){
				int a=i/j,b=j;
				if(a<=n&&a>m){
					x++;
				}
				if(a>n&&a<=m){
					y++;
				}
				if(a<=n&&a<=m){
					x++,y++;
				}
				if(a==b){
					continue;
				}
				if(b<=n&&b>m){
					x++;
				}
				if(b>n&&b<=m){
					y++;
				}
				if(b<=n&&b<=m){
					x++,y++;
				}
//				x+=(a==b?1:2);
//				cout<<x<<endl;
			}
		}
//		cout<<x<<" "<<y<<endl;
		x*=y;
		ans+=x*i;
//		cout<<endl;
	}
	cout<<ans;
	return 0;
}
